/**
 * Where to practise each subject hands-on, on platforms built for it.
 *
 * This site teaches attacks from the defender's side only (root cause, traces,
 * fixes). Every page that covers an attack, a defensive skill or a tool points
 * out to legal platforms that let you do it for real, against their own labs or
 * a lab you run yourself.
 *
 * Keys: a lesson (NNNN-name), a module (NN-MM-name), a tool guide (its slug),
 * a machine (its slug), a project (P01), a Dojo module (dojo:id) or a case file
 * (case:id). `attack` pages say they teach the defender's side and send you to
 * learn the attack itself; `practise` pages send you to do the skill.
 *
 * Every link was checked on 9 Nov 2026. HTB Academy slugs come from its
 * catalogue page, PortSwigger, pwn.college, CryptoHack and OverTheWire paths
 * from their own indexes, Atomic Red Team ids from the repository's folder list,
 * and each of those answered 200. TryHackMe answers automated requests with 429,
 * so none of its room links could be confirmed and none are listed.
 * `pnpm test:content` checks that each key is a real page and each link is
 * https (or a lab that only serves http) and listed once per page.
 */
export interface TrainLink {
  label: string;
  url: string;
}

/** "attack": the page explains an attack from the defender's side. "practice": a skill or a tool to practise. */
export type TrainKind = "attack" | "practice";

export interface Train {
  kind: TrainKind;
  links: TrainLink[];
}

const attack = (...links: TrainLink[]): Train => ({ kind: "attack", links });
const practise = (...links: TrainLink[]): Train => ({ kind: "practice", links });

const htb = (slug: string, title: string): TrainLink => ({ label: `${title} (HTB Academy)`, url: `https://academy.hackthebox.com/course/preview/${slug}` });
const ps = (path: string, label: string): TrainLink => ({ label: `${label} (Web Security Academy)`, url: `https://portswigger.net/web-security/${path}` });
const pwn = (path: string, label: string): TrainLink => ({ label: `${label} (pwn.college)`, url: `https://pwn.college/${path}/` });
const ch = (path: string, label: string): TrainLink => ({ label: `${label} (CryptoHack)`, url: `https://cryptohack.org/${path}/` });
const otw = (game: string, label: string): TrainLink => ({ label, url: `https://overthewire.org/wargames/${game}/` });
const art = (id: string, label: string): TrainLink => ({ label: `${label} (Atomic Red Team, ${id})`, url: `https://github.com/redcanaryco/atomic-red-team/blob/master/atomics/${id}/${id}.md` });
const lolbas = (name: string): TrainLink => ({ label: `${name} (LOLBAS)`, url: `https://lolbas-project.github.io/lolbas/Binaries/${name}/` });
const lab = (url: string, label: string): TrainLink => ({ label, url });

